solution.solution.cpp:
#include <cstdint>
#include <format>
#include <string>
#include <vector>

struct Module { std::string name; std::uint64_t base; std::uint64_t size; };

std::string locate(const std::vector<Module>& modules, std::uint64_t address)
{
    for (const Module& m : modules)
        if (address >= m.base && address - m.base < m.size)
            return std::format("{}+0x{:X}", m.name, address - m.base);
    return std::format("?+0x{:X}", address);
}

std::uint64_t toPreferred(std::uint64_t rva, std::uint64_t imageBase)
{
    return imageBase + rva;
}

unitTests:
const std::vector<Module> mods{ { "game.exe", 0x7FF600000000ull, 0x50000 }, { "plugin.dll", 0x7FFE20000000ull, 0x8000 } };
TEST("inside the exe") { CHECK_EQ(locate(mods, 0x7FF600012345ull), std::string("game.exe+0x12345")); }
TEST("the first byte of a module") { CHECK_EQ(locate(mods, 0x7FFE20000000ull), std::string("plugin.dll+0x0")); }
TEST("the last byte of a module") { CHECK_EQ(locate(mods, 0x7FFE20007FFFull), std::string("plugin.dll+0x7FFF")); }
TEST("just past the end is outside") { CHECK_EQ(locate(mods, 0x7FFE20008000ull), std::string("?+0x7FFE20008000")); }
TEST("no module") { CHECK_EQ(locate(mods, 0x1234), std::string("?+0x1234")); CHECK_EQ(locate({}, 0xAB), std::string("?+0xAB")); }
TEST("upper-case hex") { CHECK_EQ(locate(mods, 0x7FF60000BEEFull), std::string("game.exe+0xBEEF")); }
TEST("preferred addresses") { CHECK_EQ(toPreferred(0x12345, 0x140000000ull), 0x140012345ull); CHECK_EQ(toPreferred(0, 0x180000000ull), 0x180000000ull); }

